Fix this racy use-after-free by making sure the IRQ is requested _after_
the registration of the `power_supply` handle.

Fixes: 5069185fc18e ("power: supply: bq25980: Add support for the BQ259xx family")
Signed-off-by: Waqar Hameed <waqar.hameed@axis.com>
Link: https://patch.msgid.link/8763035cadb959e14787b3837f2d3db61f6e1c34.1766268280.git.waqar.hameed@axis.com
Signed-off-by: Sebastian Reichel <sebastian.reichel@collabora.com>

Here is the root cause:
The IRQ handler was requested using the `devm_` managed API before the power supply was registered. Since `devm_` resources are freed in reverse order during removal, this caused the power supply to be freed before the IRQ handler was unregistered, allowing a race condition where an interrupt could fire after the power supply was freed, leading to a use-after-free when `power_supply_changed()` was called. Additionally, during probe, an interrupt could fire before the power supply was initialized, causing access to an uninitialized handle.

Here is the patch:

 static int bq25980_probe(struct i2c_client *client)
 {
 	const struct i2c_device_id *id = i2c_client_get_device_id(client);
 	struct device *dev = &client->dev;
 	struct bq25980_device *bq;
 	int ret;

 	bq = devm_kzalloc(dev, sizeof(*bq), GFP_KERNEL);
 	if (!bq)
 		return -ENOMEM;

 	bq->client = client;
 	bq->dev = dev;

 	mutex_init(&bq->lock);

 	strscpy(bq->model_name, id->name, sizeof(bq->model_name));
 	bq->chip_info = &bq25980_chip_info_tbl[id->driver_data];

 	bq->regmap = devm_regmap_init_i2c(client,
 					  bq->chip_info->regmap_config);
 	if (IS_ERR(bq->regmap)) {
 		dev_err(dev, "Failed to allocate register map\n");
 		return PTR_ERR(bq->regmap);
 	}

 	i2c_set_clientdata(client, bq);

 	ret = bq25980_parse_dt(bq);
 	if (ret) {
 		dev_err(dev, "Failed to read device tree properties%d\n", ret);
 		return ret;
 	}

+	ret = bq25980_power_supply_init(bq, dev);
+	if (ret) {
+		dev_err(dev, "Failed to register power supply\n");
+		return ret;
+	}
+
 	if (client->irq) {
 		ret = devm_request_threaded_irq(dev, client->irq, NULL,
 						bq25980_irq_handler_thread,
 						IRQF_TRIGGER_FALLING |
 						IRQF_ONESHOT,
 						dev_name(&client->dev), bq);
 		if (ret)
 			return ret;
 	}

-	ret = bq25980_power_supply_init(bq, dev);
-	if (ret) {
-		dev_err(dev, "Failed to register power supply\n");
-		return ret;
-	}
-
 	ret = bq25980_hw_init(bq);
 	if (ret) {
 		dev_err(dev, "Cannot initialize the chip.\n");
 		return ret;
 	}

 	return 0;
 }



